def shapes(g):
    H_,W_=len(g),len(g[0]); seen=[[False]*W_ for _ in range(H_)]; res=[]
    for r_ in range(H_):
        for c_ in range(W_):
            if g[r_][c_] and not seen[r_][c_]:
                col=g[r_][c_]; stack=[(r_,c_)]; seen[r_][c_]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H_ and 0<=nx<W_ and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                res.append((col,min(ys),max(ys),min(xs),max(xs),len(cells),tuple(sorted(cells))))
    return res
