def solve(g):
    H_,W_=len(g),len(g[0])
    out=[[0]*W_ for _ in range(H_)]
    def is_ring(cells):
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        return len(cells)==2*(r1-r0+1)+2*(c1-c0+1)-4 and r1>r0+1 and c1>c0+1
    sh=shapes(g)
    rings=sorted([s_ for s_ in sh if is_ring(s_[6])],key=lambda s_:s_[1])
    crosses=sorted([s_ for s_ in sh if not is_ring(s_[6])],key=lambda s_:-s_[2])  # bottom-most first
    for s_ in rings:
        cells=s_[6]; top=0
        while True:
            oc={(r_-s_[1]+top,c_) for (r_,c_) in cells}
            if any(r_<0 or r_>=H_ or c_<0 or c_>=W_ or out[r_][c_] for r_,c_ in oc): top+=1; continue
            break
        for (r_,c_) in cells: out[r_-s_[1]+top][c_]=s_[0]
    for s_ in crosses:
        cells=s_[6]; bot=H_-1
        while True:
            oc={(r_-s_[2]+bot,c_) for (r_,c_) in cells}
            if any(r_<0 or out[r_][c_] for r_,c_ in oc): bot-=1; continue
            break
        for (r_,c_) in cells: out[r_-s_[2]+bot][c_]=s_[0]
    return out
